import{_ as t,o,c as a,aS as r}from"./chunks/framework.6vsn32Qq.js";const f=JSON.parse('{"title":"从消费者提取公共能力的流程","description":"","frontmatter":{},"headers":[],"relativePath":"migration/extraction-workflow.md","filePath":"migration/extraction-workflow.md","lastUpdated":null}'),n={name:"migration/extraction-workflow.md"};function l(s,e,i,c,d,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="从消费者提取公共能力的流程" tabindex="-1">从消费者提取公共能力的流程 <a class="header-anchor" href="#从消费者提取公共能力的流程" aria-label="Permalink to &quot;从消费者提取公共能力的流程&quot;">​</a></h1><ol><li><strong>盘点真实消费者。</strong> 从源码、<code>package.json</code>、lockfile、alias 与可运行用例确认调用点；<code>qy-workspace</code> 只提供旧 ERP 证据，不能直接当作迁移模板。</li><li><strong>冻结业务与公共职责。</strong> 写清可复用的交互、宿主必须保留的 API/payload/权限/状态，以及不在本轮处理的兼容债务。</li><li><strong>设计 Qy interface。</strong> 用 Qy 自有 props、events、slots、expose 和 tokens 定义稳定面；不新增 Element Plus 类型、实例、私有 DOM/VNode/Node/Store、私有事件或 <code>--el-*</code> 依赖。</li><li><strong>实现内部 implementation/adapter。</strong> 当前实现可使用 Element Plus；只在真实行为差异、复杂受控状态、浮层/focus、递归节点、厂商回调边界或第二实现出现时建立明确 seam。</li><li><strong>由新消费者验收。</strong> 选择目标消费者的真实页面、解析配置和最小测试/构建入口，证明公开 Qy interface；旧项目只能辅助对照行为。</li><li><strong>发布。</strong> 核对目标包 exports、声明、运行时代码、发布产物和 release record。此时才能将能力从 Implemented 更新为 Published。</li><li><strong>旧消费者渐进采用。</strong> 每个消费者独立通过自己的 package metadata、lockfile 和接入验收记录更新为 Adopted；不得把一个项目的版本或本地 alias 视为全局状态。</li></ol><p>提取项的排队与状态更新见 <a href="./../catalog/component-lifecycle">公共能力生命周期</a>，消费者证据见 <a href="./../consumers/README">消费者索引</a>，renderer 取舍见 <a href="./../adr/2026-08-06-current-element-implementation-and-future-renderer-seam">当前 Element Plus implementation ADR</a>。</p>',3)])])}const g=t(n,[["render",l]]);export{f as __pageData,g as default};
